<?php
namespace NirmaanBuilder;
if(!defined('ABSPATH')){exit;}
class Renderer {
 private $style_presets=null;\n private function get_style_preset($id){if(!$id)return array();if(null===$this->style_presets){$items=get_option('nirmaan_builder_style_presets',array());$this->style_presets=is_array($items)?$items:array();}return $this->style_presets[$id]['styles']??array();}
 public function hooks(){add_filter('the_content',array($this,'filter_content'),20);add_action('wp_body_open',array($this,'render_header'),5);add_action('wp_footer',array($this,'render_footer'),5);add_action('wp_enqueue_scripts',array($this,'enqueue_styles'));}
 public function enqueue_styles(){wp_enqueue_style('nirmaan-builder-frontend',NIRMAAN_BUILDER_URL.'assets/css/frontend.css',array(),NIRMAAN_BUILDER_VERSION);}
 private function assigned_template(){$templates=get_posts(array('post_type'=>'nirmaan_template','post_status'=>'publish','numberposts'=>200,'meta_key'=>'_nirmaan_priority','orderby'=>'meta_value_num','order'=>'DESC'));foreach($templates as $t){$c=get_post_meta($t->ID,'_nirmaan_conditions',true);if($this->matches_conditions(is_array($c)?$c:array()))return $t->ID;}return 0;}
 private function matches_conditions($c){$inc=$c['include']??array();$exc=$c['exclude']??array();$match=false;foreach($inc as $r)if($this->matches_rule($r)){$match=true;break;}if(!$match)return false;foreach($exc as $r)if($this->matches_rule($r))return false;return true;}
 private function matches_rule($r){if(!is_array($r)||empty($r['type']))return false;$t=sanitize_key($r['type']);$v=absint($r['value']??0);switch($t){case'entire_site':return true;case'front_page':return is_front_page();case'singular':return is_singular()&&$v===get_queried_object_id();case'all_pages':return is_page();case'all_posts':return is_single()&&'post'===get_post_type();case'post_type':return is_singular(sanitize_key($r['post_type']??''));case'archive':return is_archive();case'search':return is_search();case'404':return is_404();case'product':return function_exists('is_product')&&is_product();case'product_archive':return function_exists('is_product_category')&&(is_shop()||is_product_taxonomy());case'shop':return function_exists('is_shop')&&is_shop();case'cart':return function_exists('is_cart')&&is_cart();case'checkout':return function_exists('is_checkout')&&is_checkout();default:return false;}}
 public function filter_content($content){if(is_admin()||!is_main_query()||!in_the_loop())return $content;$doc=get_post_meta(get_the_ID(),'_nirmaan_builder_document',true);if(is_array($doc)&&!empty($doc['nodes']))return $this->render_nodes($doc['nodes']);$id=$this->assigned_template();if($id){$parts=get_post_meta($id,'_nirmaan_template_parts',true);if(!empty($parts['body']['nodes']))return $this->render_nodes($parts['body']['nodes']);}return $content;}
 public function render_header(){$this->render_part('header');}public function render_footer(){$this->render_part('footer');}
 private function render_part($part){if(is_admin())return;$id=$this->assigned_template();if(!$id)return;$parts=get_post_meta($id,'_nirmaan_template_parts',true);if(isset($parts[$part]['nodes'])&&is_array($parts[$part]['nodes']))echo $this->render_nodes($parts[$part]['nodes']);}
 private function woo($type){if(!function_exists('wc_get_product'))return '<p class="nb-notice">WooCommerce is required for this element.</p>';if('cart'===$type)return do_shortcode('[woocommerce_cart]');if('checkout'===$type)return do_shortcode('[woocommerce_checkout]');if('product_archive'===$type)return do_shortcode('[products limit="12" columns="4" paginate="true"]');if('mini_cart'===$type){ob_start();if(function_exists('woocommerce_mini_cart'))woocommerce_mini_cart();return '<div class="nb-mini-cart">'.ob_get_clean().'</div>';}if('related_products'===$type)return do_shortcode('[related_products limit="4"]');if('shop_products'===$type)return do_shortcode('[products limit="8" columns="4"]');global $product;if(!$product&&get_the_ID())$product=wc_get_product(get_the_ID());if(!$product)return ''; $map=array('product_title'=>'woocommerce_template_single_title','product_price'=>'woocommerce_template_single_price','product_image'=>'woocommerce_show_product_images','product_add_to_cart'=>'woocommerce_template_single_add_to_cart','product_description'=>'woocommerce_template_single_excerpt','product_rating'=>'woocommerce_template_single_rating');if(empty($map[$type])||!function_exists($map[$type]))return '';ob_start();call_user_func($map[$type]);return ob_get_clean();}
 public function render_nodes($nodes){if(!is_array($nodes))return '';$html='';foreach(array_slice($nodes,0,300) as $n){if(!is_array($n))continue;$type=sanitize_key($n['type']??'');$s=is_array($n['settings']??null)?$n['settings']:array();$content=$s['content']??'';$classes='nb-node';$fallback=is_array($s['preset_fallback']??null)?$s['preset_fallback']:array();$preset=$this->get_style_preset(sanitize_key($s['style_preset_id']??''));$base_style=array_merge($fallback['desktop']??array(),$preset['desktop']??array(),$s['desktop']??array());$style=$this->inline_style($base_style);$responsive='';foreach(array('tablet','mobile') as $device){$device_style=array_merge($fallback[$device]??array(),$preset[$device]??array(),$s[$device]??array());$d=$this->inline_style($device_style);if($d)$responsive.='@media (max-width:'.('tablet'===$device?'1024px':'767px').'){.nb-node-'.sanitize_html_class($n['id']??'').'{'.$d.'}}';}foreach(array('desktop','tablet','mobile') as $device)if(!empty($s['hide_'.$device]))$responsive.='@media ('.('desktop'===$device?'min-width:1025px':('tablet'===$device?'min-width:768px) and (max-width:1024px':'max-width:767px')).'){.nb-node-'.sanitize_html_class($n['id']??'').'{display:none!important}}';$id='nb-node-'.sanitize_html_class($n['id']??wp_generate_uuid4());if($responsive)$html.='<style>'.$responsive.'</style>';
  if('global_element'===$type){$gid=absint($s['library_id']??0);$g=get_post_meta($gid,'_nirmaan_library_document',true);if($gid&&get_post_meta($gid,'_nirmaan_global',true)&&is_array($g))$html.=$this->render_nodes($g['nodes']??array());continue;}
  if(in_array($type,array('product_title','product_price','product_image','product_add_to_cart','product_description','product_rating','related_products','shop_products','cart','checkout','mini_cart','product_archive'),true)){$html.='<div class="nb-node '.$id.'" style="'.$style.'">'.$this->woo($type).'</div>';continue;}
  switch($type){case'heading':$l=min(6,max(1,absint($s['level']??2)));$html.=sprintf('<h%d class="nb-heading nb-node %s" style="%s">%s</h%d>',$l,esc_attr($id),esc_attr($style),esc_html($content),$l);break;case'text':$html.='<div class="nb-text nb-node '.esc_attr($id).'" style="'.esc_attr($style).'">'.wp_kses_post($content).'</div>';break;case'image':$u=esc_url($s['url']??'');if($u)$html.='<figure class="nb-image nb-node '.esc_attr($id).'" style="'.esc_attr($style).'"><img src="'.$u.'" alt="'.esc_attr($s['alt']??'').'" loading="lazy"></figure>';break;case'button':$html.='<p class="nb-button-wrap nb-node '.esc_attr($id).'" style="'.esc_attr($style).'"><a class="nb-button" href="'.esc_url($s['url']??'#').'">'.esc_html($content?:__('Button','nirmaan-builder')).'</a></p>';break;case'divider':$html.='<hr class="nb-divider nb-node '.esc_attr($id).'" style="'.esc_attr($style).'">';break;case'spacer':$h=min(1200,absint($s['height']??32));$html.='<div class="nb-spacer nb-node '.esc_attr($id).'" style="height:'.$h.'px;'.$style.'"></div>';break;case'container':case'columns':$html.='<div class="nb-container nb-node '.esc_attr($id).'" style="'.esc_attr($style).'">'.$this->render_nodes($n['children']??array()).'</div>';break;}
 }return $html;}
 private function inline_style($s){
  if(!is_array($s))return '';
  $map=array('padding'=>'padding','margin'=>'margin','fontSize'=>'font-size','fontWeight'=>'font-weight','lineHeight'=>'line-height','letterSpacing'=>'letter-spacing','color'=>'color','backgroundColor'=>'background-color','borderColor'=>'border-color','borderWidth'=>'border-width','borderStyle'=>'border-style','textAlign'=>'text-align','width'=>'width','maxWidth'=>'max-width','minHeight'=>'min-height','borderRadius'=>'border-radius','boxShadow'=>'box-shadow','opacity'=>'opacity','display'=>'display','gap'=>'gap','flexDirection'=>'flex-direction','justifyContent'=>'justify-content','alignItems'=>'align-items');
  $shadows=array('none'=>'none','soft'=>'0 2px 8px rgba(15,23,42,.08)','medium'=>'0 6px 18px rgba(15,23,42,.14)','strong'=>'0 12px 32px rgba(15,23,42,.22)');
  $out='';
  foreach($map as $key=>$property){
   if(!isset($s[$key])||''===$s[$key])continue;
   $value=$s[$key];
   if('boxShadow'===$key)$value=$shadows[$value]??'none';
   if(in_array($key,array('color','backgroundColor','borderColor'),true))$value=sanitize_hex_color($value)?:'';
   else $value=esc_attr($value);
   if(''!==$value)$out.=$property.':'.$value.';';
  }
  return $out;
 }
}
